import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Comments and Naming Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/comments-and-naming-conventions.md","filePath":"your-first-al-programs/comments-and-naming-conventions.md"}`),a={name:`your-first-al-programs/comments-and-naming-conventions.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="comments-and-naming-conventions" tabindex="-1">Comments and Naming Conventions <a class="header-anchor" href="#comments-and-naming-conventions" aria-label="Permalink to “Comments and Naming Conventions”">​</a></h1><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to “Comments”">​</a></h2><p><strong>Comments</strong> are notes written inside code to explain its purpose. They are ignored by the compiler and do not affect program execution.</p><p>AL supports single-line comments using <code>//</code>.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Calculate the total price including tax</span></span>
<span class="line"><span>TotalAmount := Subtotal + Tax;</span></span></code></pre></div><p>AL also supports block comments:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/* Calculate total price including tax */</span></span>
<span class="line"><span>TotalAmount := Subtotal + Tax;</span></span></code></pre></div><p>Comments are useful for explaining business rules or decisions that might not be obvious from the code.</p><h3 id="xml-documentation-comments" tabindex="-1">XML Documentation Comments <a class="header-anchor" href="#xml-documentation-comments" aria-label="Permalink to “XML Documentation Comments”">​</a></h3><p>AL also supports XML documentation comments, which begin with <code>///</code>. These can document procedures and other elements, helping developers understand your code through IntelliSense in Visual Studio Code.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/// Calculates the discount for an eligible customer.</span></span>
<span class="line"><span>local procedure CalculateDiscount(Amount: Decimal): Decimal</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    exit(Amount * 0.10);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Unlike ordinary comments, XML documentation comments can provide structured documentation for other developers.</p><h2 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to “Naming Conventions”">​</a></h2><p><strong>Naming conventions</strong> are agreed-upon rules for naming variables, procedures, fields, and objects consistently.</p><p>Good names make code easier to read, understand, and maintain.</p><h3 id="pascalcase" tabindex="-1">PascalCase <a class="header-anchor" href="#pascalcase" aria-label="Permalink to “PascalCase”">​</a></h3><p>AL commonly uses <strong>PascalCase</strong>, where each word starts with a capital letter.</p><p>Examples:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    CustomerName: Text[100];</span></span>
<span class="line"><span>    TotalAmount: Decimal;</span></span>
<span class="line"><span>    IsOrderApproved: Boolean;</span></span></code></pre></div><p>Use meaningful names that describe what an identifier represents.</p><table tabindex="0"><thead><tr><th>Avoid</th><th>Prefer</th></tr></thead><tbody><tr><td><code>x</code></td><td><code>TotalAmount</code></td></tr><tr><td><code>cust</code></td><td><code>CustomerName</code></td></tr><tr><td><code>flag</code></td><td><code>IsOrderApproved</code></td></tr><tr><td><code>calc</code></td><td><code>CalculateDiscount</code></td></tr></tbody></table><h3 id="naming-al-objects" tabindex="-1">Naming AL Objects <a class="header-anchor" href="#naming-al-objects" aria-label="Permalink to “Naming AL Objects”">​</a></h3><p>Give objects descriptive names that communicate their purpose.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>table 50100 Employee</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Table definition</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>page 50101 EmployeeList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Page definition</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codeunit 50102 EmployeeManagement</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Business logic</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>These names make it easy to identify what each object does.</p><h3 id="naming-variables-that-reference-objects" tabindex="-1">Naming Variables That Reference Objects <a class="header-anchor" href="#naming-variables-that-reference-objects" aria-label="Permalink to “Naming Variables That Reference Objects”">​</a></h3><p>When a variable references a Business Central object, include the object&#39;s name in the variable name where practical.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    Customer: Record Customer;</span></span>
<span class="line"><span>    SalesHeader: Record &quot;Sales Header&quot;;</span></span></code></pre></div><p>This makes it clear which records the variables represent.</p><h2 id="file-naming-conventions" tabindex="-1">File Naming Conventions <a class="header-anchor" href="#file-naming-conventions" aria-label="Permalink to “File Naming Conventions”">​</a></h2><p>Microsoft recommends including the object name and object type in AL filenames.</p><p>For example:</p><table tabindex="0"><thead><tr><th>Object</th><th>Recommended filename</th></tr></thead><tbody><tr><td>Employee table</td><td><code>Employee.Table.al</code></td></tr><tr><td>Employee list page</td><td><code>EmployeeList.Page.al</code></td></tr><tr><td>Employee management codeunit</td><td><code>EmployeeManagement.Codeunit.al</code></td></tr><tr><td>Customer table extension</td><td><code>CustomerExtension.TableExt.al</code></td></tr></tbody></table><p>Consistent filenames make it easier to locate objects as your project grows.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/compliance/apptest-bestpracticesforalcode" target="_blank" rel="noreferrer">Best Practices for AL Code</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-xml-comments" target="_blank" rel="noreferrer">XML Documentation Comments in AL</a></li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p><strong>Comments explain code, while naming conventions make code easier to understand and maintain.</strong> Use comments to clarify important business rules, choose meaningful PascalCase identifiers, and follow consistent naming conventions for objects and files.</p>`,38)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};